// --- Scope Hierarchy and Permission Checking Utilities ---
exports.IMPLIED_SCOPES = {
    all_branches: new Set([
        'all_branches',
        'selected_branches',
        'own_branch',
        'selected_departments',
        'own_department',
        'assigned_class',
        'assigned_subject',
        'own_record',
    ]),
    selected_branches: new Set([
        'selected_branches',
        'own_branch',
        'own_department',
        'assigned_class',
        'assigned_subject',
        'own_record',
    ]),
    own_branch: new Set([
        'own_branch',
        'own_department',
        'assigned_class',
        'assigned_subject',
        'own_record',
    ]),
    selected_departments: new Set(['selected_departments', 'own_department', 'own_record']),
    own_department: new Set(['own_department', 'own_record']),
    assigned_class: new Set(['assigned_class', 'own_record']),
    assigned_subject: new Set(['assigned_subject', 'own_record']),
    own_record: new Set(['own_record']),
};
/**
 * Checks whether user permissions and roles satisfy the required permission
 * with action inheritance (manage/edit -> view) and scope hierarchy.
 */
function checkUserPermission(userPermissions, requiredPermission, _userRoles = []) {
    const permSet = userPermissions instanceof Set ? userPermissions : new Set(userPermissions);
    if (permSet.has('*')) {
        return true;
    }
    const normalizedRequired = requiredPermission.replace(/:/g, '.').trim();
    // 1. Direct match
    if (permSet.has(normalizedRequired)) {
        return true;
    }
    const requiredParts = normalizedRequired.split('.');
    if (requiredParts.length < 3) {
        return false;
    }
    const reqModule = requiredParts[0] ?? '';
    const reqAction = requiredParts.slice(1, -1).join('.');
    const reqScope = requiredParts.at(-1) ?? '';
    for (const rawPerm of permSet) {
        const perm = rawPerm.replace(/:/g, '.').trim();
        if (perm === normalizedRequired || perm === '*') {
            return true;
        }
        const permParts = perm.split('.');
        if (permParts.length < 3) {
            continue;
        }
        const userModule = permParts[0] ?? '';
        const userAction = permParts.slice(1, -1).join('.');
        const userScope = permParts.at(-1) ?? '';
        if (userModule !== reqModule && userModule !== '*') {
            continue;
        }
        // Action matching (exact, or 'manage', or '*', or 'edit' covers 'view')
        const actionMatches = userAction === reqAction ||
            userAction === 'manage' ||
            userAction === '*' ||
            (reqAction === 'view' && userAction === 'edit');
        if (!actionMatches) {
            continue;
        }
        if (exports.IMPLIED_SCOPES[userScope]?.has(reqScope)) {
            return true;
        }
    }
    return false;
}
